mapper.select:
SELECT EXISTS( SELECT 1 FROM tbl_dim_team WHERE deleted_at IS NULL AND status = 'ACTIVE' AND LOWER(team_code) = LOWER(#{teamCode})
AND team_id <> #{excludeTeamId}
)

SELECT EXISTS(
    SELECT 1
    FROM tbl_team_member
    WHERE team_id = #{teamId}
      AND member_key = #{memberKey}
      AND deleted_at IS NULL
      AND status = 'ACTIVE'

          AND team_member_id <> #{excludeTeamMemberId}

)

mapper.update:
UPDATE tbl_team_member
SET role_id = #{roleId},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy},
    version = version + 1
WHERE team_member_id = #{teamMemberId}
  AND team_id = #{teamId}
  AND version = #{version}
  AND deleted_at IS NULL
  AND status = 'ACTIVE'

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM tbl_dim_member_pseudonym
    WHERE member_key = #{memberKey}
      AND (active_to IS NULL OR active_to >= CURRENT_DATE)
)

SELECT EXISTS(
    SELECT 1
    FROM tbl_dim_role
    WHERE role_id = #{roleId}
)
